def segments(grid):
    segs=[]
    for row in grid:
        nz=[j for j,v in enumerate(row) if v]
        if len(nz)>1:
            segs.append((nz[0], row[nz[0]:nz[-1]+1]))
    return segs

def f(grid):
    segs=segments(grid)
    out=[r[:] for r in grid]
    for i,row in enumerate(grid):
        for j,v in enumerate(row):
            if v and len([x for x in row if x])==1:
                cands=[s for s in segs if v in s[1]]
                st,seq=cands[0]
                k=seq.index(v)
                start=j-k
                for t,c in enumerate(seq):
                    jj=start+t
                    if 0<=jj<len(grid[0]): out[i][jj]=c
    return out

